-- Update provider institution details
UPDATE provider_institution SET
    intake_date = 'February, April, July, October',
    updated_at = NOW()
WHERE cricos_provider_code = '00001K';

UPDATE courses SET
    course_description = '<p>This course equips you with the technical, creative and conceptual skills to create impactful designs that solve visual communication challenges and meet client needs.</p><p>Through this course, you’ll learn to interpret briefs and develop solutions using typography, illustration, photography and layouts. Your practice will be guided by design theory and enhanced by critical analysis, enabling you to synthesise information and generate innovative ideas.</p><p>With applications across print and digital media, this course prepares you to work in diverse commercial and community contexts. Gain the skills to deliver effective visual communication for clients in various industries and establish yourself in the dynamic field of graphic design.</p>',
    total_course_duration = '<p><strong>TOTAL CIT PACKAGE: 2 years</strong></p><p>Diploma 1.5 years</p><p>Advanced Diploma 6 months with completion of the Diploma in Graphic Design with CIT</p><p><em>Advanced Diploma 12 months if Diploma of Graphic Design has been completed with another provider.</em></p>',
    offshore_tuition_fee = 25470,
    onshore_tuition_fee = 25470,
    enrolment_fee = NULL,
    materials_fee = 1529,
    entry_requirements = '<h4>Entry Requirements</h4> <p><strong>Academic requirements:</strong></p><ul><li>Year 12 Certificate or equivalent</li><li>Interview (or other negotiated process)</li><li>A portfolio of recent work or work that demonstrates your aptitude for design. Portfolios may contain examples of design solutions from a range of activities and media types and may include drawing, photography, painting, printmaking or any graphic design projects you have undertaken</li></ul><p><strong>Literacy Skills Information</strong></p><p>We suggest that you will need Australian Core Skills Framework literacy levels of at least 4 across reading, writing, learning, oral communication and, depending on your course of study, numeracy skills to successfully complete this course. If you do not have this level, you can still enrol and seek support to improve your skills or you may prefer to begin with the lower level course.</p><p><br/>Students over the age of 20 may be eligible for adult entry. Please refer to <a href="https://international.cit.edu.au/apply/entry_requirements">Entry Requirements</a> for more information.</p><p><strong>English requirements</strong></p><p>Students must meet <strong>one</strong> of the following English requirements:</p><ul><li>IELTS 6.0 (no band score less than 5.0)</li><li>PTE Academic - 50 (minimum of 36 in each band)</li><li>Cambridge English test (C1 Advanced and B2 First) - 169</li></ul><p><b> Portfolio Requirements </b><br/> Individuals must provide evidence of their technical skills and ability to:</p><ul><li>produce multiple examples of graphic design work that meets different design requirements.</li><li>produce typography that supports the overall design solution.</li><li>use graphic design industry software.</li><li>Skills and knowledge may have been acquired through personal or work experience or formal study.</li><li><i>(You will need to collect and retain confirmed evidence of any entry requirements if stated)</i></li></ul>',
    apply_form = 'https://international.cit.edu.au/courses/art_design_multimedia/graphic_design',
    updated_at = NOW()
WHERE cricos_course_code = '105812B';

