UPDATE courses SET
    course_description = '<p>Providing expert care and support to people with disability is a growing sector in Australia, and there is demand for workers in a variety of roles within residential facilities, private homes and the community.</p><p>Develop the skills, knowledge and hands on experience to perform all the functions of a disability support worker or progress to the Certificate IV and gain the ability to provide, coordinate and supervise home and community support programs.</p><p><strong>Industry Placement</strong></p><p>You will receive a minimum of 120 unpaid hours of industry experience fully coordinated by CIT. This industry placement will give you the firsthand skills to be ready for employment.</p>',
    total_course_duration = '<p><strong>TOTAL CIT PACKAGE: 6 months</strong><br/>Certificate III: 6 months</p>',
    offshore_tuition_fee = 7830,
    onshore_tuition_fee = 7830,
    enrolment_fee = NULL,
    materials_fee = 502,
    entry_requirements = '<h4>Entry Requirements</h4> <p><strong>Academic requirements:</strong></p><ul><li>Year 12 Certificate (or equivalent)</li></ul><p><br/>Students over the age of 20 may be eligible for adult entry with relevant practical work or other professional experience. Please refer to <a href="https://international.cit.edu.au/apply/entry_requirements">Entry Requirements</a> for more information.</p><p><strong>English requirements:</strong><br/><strong>Students must also meet one of the following English requirements:</strong></p><ul><li>IELTS 6.0 (no band score less than 5.0)</li><li>PTE Academic - 50 (minimum of 36 in each band)</li><li>Cambridge English test (C1 Advanced and B2 First) - 169</li></ul><p>Non-student visa applicants who hold a temporary visa for the full duration of the offered program will be required to meet Australian Core Skills Framework literacy levels of at least 3 in Language, Literacy, Numeracy and Digital skills (LLND) or equivalent.</p><p>Students also require an expressed interest in working with people who live with issues of disability. Applicants may be interviewed to demonstrate interest in complex client support, human rights and person-centred frameworks and genuine interest to work with diverse colleagues and clients.</p>',
    apply_form = 'https://international.cit.edu.au/courses/health_community/disability',
    updated_at = NOW()
WHERE cricos_course_code = '114025K';

UPDATE courses SET
    course_description = '<p>Want a meaningful career that helps your community? Our rewarding qualifications in mental health support or community services will give you the opportunity to help people in a wide range of settings.</p><p><br/>Gain the skills, techniques and hands-on experience you need to work as a support worker in mental health. Learn how to provide a range of assistance measures to clients with mental health issues and implement health promotion within the community services context. The diploma allows you to delve further into your knowledge of community welfare, gaining enhanced experience in community engagement, supplying advanced interventions to clients as well as learning how to respond to crises.</p>Industry Placement<p>Get 80 unpaid hours of industry experience with an industry placement! This will give you the firsthand skills to be ready for employment. CIT teachers co-ordinate placement.</p><p>(Certificate IV: 80 unpaid hours.)</p>Why Study at CIT?<ul><li>Hands-on industry experience</li><li>Many job opportunities in Canberra and throughout Australia</li></ul>',
    total_course_duration = '<p>1 year</p>',
    offshore_tuition_fee = 16980,
    onshore_tuition_fee = 16980,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4> <p><strong>Academic requirements:</strong></p><ul><li>Year 12 Certificate (or equivalent)</li></ul><p><br/>Students over the age of 20 may be eligible for adult entry with relevant practical work or other professional experience. Please refer to <a href="https://international.cit.edu.au/apply/entry_requirements">Entry Requirements</a> for more information.</p><p><strong>English requirements:</strong><br/><strong>Student must also meet one of the following English requirements:</strong></p><ul><li>IELTS 6.0 (no band score less than 5.0)</li><li>PTE Academic - 50 (minimum of 36 in each band)</li><li>Cambridge English test (C1 Advanced and B2 First) - 169</li><p>Nonstudent visa applicants who hold a temporary visa for the full duration of the offered program will be required to meet Australian Core Skills Framework literacy levels of at least 3 in across reading, writing, learning, oral communication and, depending on your course of study, numeracy skills or equivalent.</p></ul><p><strong>Other requirements:</strong></p><p>Before undertaking any industry placement, you must be eligible to apply for and hold a ''Working with Vulnerable People Check''. Information will be provided on enrolment</p>',
    apply_form = 'https://international.cit.edu.au/courses/health_community/mental_health',
    updated_at = NOW()
WHERE cricos_course_code = '091155E';

UPDATE courses SET
    course_description = '<p>Nursing is a respected and growing industry that is essential for the health of the community. Our Diploma course prepares you to work as an Enrolled Nurse under the supervision of a registered nurse in a variety of healthcare settings, including hospitals, aged care, primary health, GP clinics, community settings and mental health.</p><p>CIT’s Diploma of Nursing is fully accredited by the <a href="https://www.anmac.org.au/#:~:text=The%20Australian%20Nursing%20and%20Midwifery,for%20nursing%20and%20midwifery%20education.">Australian Nursing &amp; Midwifery Accreditation Council</a> (ANMAC). This means, when you complete your studies at CIT, you will be eligible to apply for your <a href="https://www.ahpra.gov.au">Australian Health Practitioner Regulation Agency</a> (AHPRA) registration to become an Enrolled Nurse right away!</p>Industry Placement<p>You are required to complete 400 hours of Professional Experience Placement (PEP) to successfully complete the course and to satisfy Australian Health Practitioner Regulation Agency (AHPRA’s) requirements for your qualification.</p><p>You will be required to work shifts determined by your placement provider and this will be between Monday to Friday morning, afternoon and night shifts. Some facilities may schedule placements on weekends and public holidays.</p><p>Shift times are generally between 7am and 10pm, unless you are rostered for night duty, which is 9pm–7:30 am.</p><p>Completing placement is compulsory, and you will be expected to manage family and work commitments to complete your shifts.</p><p>Placements are provided in areas such as: Acute Care, Aged Care, Mental Health Rehabilitation, Community Nursing and Palliative Care.</p><p>All placements are organised by CIT, and we will place you at a chosen industry provider.</p><p>Important note: A student who is pregnant cannot attend Professional Experience Placement for a period commencing six (6) weeks prior to the estimated date of delivery. A student can return to placement six (6) weeks after the actual date of birth, provided they submit a doctor''s letter of fitness from a registered medical practitioner confirming they are fit to return to nursing duties.</p>Why study nursing at CIT?<ul><li>Ultramodern, on-campus training hospital facility</li><li>Clinical industry placement fully coordinated by CIT</li><li>Fully accredited by the Australian Nursing and Midwifery Accreditation Council (ANMAC)</li><li>Be eligible to apply for your Australian Health Practitioner Regulation Agency (AHPRA) registration to become an Enrolled Nurse right away!</li><li>Many job opportunities in Canberra and throughout Australia</li><li>The training of Nursing professionals at CIT is led by teachers whose inspiration and expertise prepares students for their future caring role and a rewarding career. <a href="https://www.youtube.com/watch?v=fUSQ9NVXOSg">Take a look at how CIT are preparing work ready nurses</a>.</li></ul>',
    total_course_duration = '<p><strong>TOTAL CIT PACKAGE: 1.5 years</strong><br/>Diploma of Nursing: 1.5 years including a combination of online learning, face-to-face learning and skill development in the Simulated Laboratory (3- 4 days per week in class and simulated labs). Includes mandatory Professional experience placement.</p>',
    offshore_tuition_fee = 29820,
    onshore_tuition_fee = 29820,
    enrolment_fee = NULL,
    materials_fee = 5900,
    entry_requirements = '<h4>Entry Requirements</h4> <p><strong>Academic requirements:</strong></p><ul><li>You must be at least 18 years of age to apply for this qualification.</li><li>Year 12 Certificate (or equivalent) with at least a “C” grade average in English and Maths (completed within the last 10 years) Please provide evidence of your most recent and highest completed level of completed studies.</li><li>Language, literacy, numeracy and digital (LLND) - Australian Core Skills Framework literacy levels of at least 4 across reading, writing, learning, oral communication. Administered by CIT International after application submission.</li><li>ACT <a href="https://www.accesscanberra.act.gov.au/business-and-work/working-with-vulnerable-people/apply-for-or-renew-a-wwvp-registration">Working With Vulnerable People (WWVP) Card</a> – Evidence of application submission $157 approx.</li><li>A police check – from the <a href="https://www.afp.gov.au">Australian Federal Police</a> for “Code 8” - Hospital Employment ($56 approx) – Evidence of application submission (Digital Certificate).</li></ul><p><strong>Pre-placement compliance documentation:</strong></p><ul><li>*Pre- placement documentation is required to be provided and approved by the Nursing Department no later than Week 1 of study.</li><li>All placements are organised by CIT at a chosen industry provider.</li><li><a href="https://international.cit.edu.au/courses/health_community/nursing/inherent-nursing-requirements.pdf">Inherent Nursing requirements (PDF, 290.84 KB)</a></li><li><a href="https://international.cit.edu.au/courses/health_community/nursing/faq-for-diploma-of-nursing-HLT54121.pdf">FAQ for Diploma of Nursing (PDF, 731.1 KB)</a></li><li>A police check – from the <a href="https://www.afp.gov.au">Australian Federal Police</a> for “Code 8” - Hospital Employment ($56 approx)</li><li>ACT <a href="https://www.accesscanberra.act.gov.au/business-and-work/working-with-vulnerable-people/apply-for-or-renew-a-wwvp-registration">Working With Vulnerable People (WWVP) Card</a> (front and back) $157 approx.</li><li>A letter from a General Practitioner confirming fitness to work as a nurse (cost of a general consultation) - please use letter from this link <a href="https://international.cit.edu.au/courses/health_community/nursing/General-Practitioner-letter.pdf">General practitioner''s letter (PDF, 452.56 KB)</a></li><li>Evidence of current immunisation status for the following: <ul><li>Hepatitis B with titre</li><li>Measles, Mumps, Rubella (MMR)</li><li>Varicella (chicken pox)</li><li>Diphtheria/Tetanus/Pertussis (dTpa) - (Evidence of one adult vaccine within the last 10 years</li><li>Influenza - An annual influenza vaccination is required for placements taking place between 1 June and 30 September each year.</li><li>Tuberculosis – (TB) screening - Students are required to undergo a Tuberculosis (TB) screening prior to their first clinical placement.</li><li>Covid-19 vaccination – evidence of 3 vaccinations</li></ul></li><li>(up to $400 approx.) <a href="https://international.cit.edu.au/courses/health_community/nursing/cit-vaccination-card.pdf">CIT Vaccination Card (PDF, 351.99 KB)</a></li><li>First Aid certificate (HLTAID011) required to be valid ($150-$250 approx.)</li></ul><p><strong>English requirements:</strong></p><p>ENGLISH REQUIREMENT for tests taken on or before 22 April 2026:</p><p><strong>Cambridge - </strong>C1 Advanced or C2 Proficiency (Paper and computer at test centre only)</p><p><strong>Minimum score of:</strong></p><ul><li>185 in listening, reading and speaking, and</li><li>176 in writing.</li></ul><p><strong>IELTS – </strong>Academic paper and computer at test centre only.</p><p><strong>Overall score of 7 comprising of a minimum score of:</strong></p><ul><li>7 for listening, reading and speaking, and</li><li>6.5 for writing.</li></ul><p><strong>OET – </strong>(On paper or computer based in testing centre). Any profession-specific OET test can be accepted.</p><p>Minimum overall score not applicable.</p><ul><li>Minimum score of B for listening, reading and speaking</li><li>Minimum score of C+ for writing.</li></ul><p><strong>PTE Academic </strong>(Computer at test centre only)</p><p>Minimum overall score of 66 comprising of a minimum score of:</p><ul><li>66 for listening, reading and speaking, and</li><li>56 for writing.</li></ul><p><strong>TOEFL iBT </strong>(Computer at test centre only)</p><p>Minimum total score of 94 with the following minimum band scores:</p><ul><li>24 for listening, 24 for reading, 24 for writing, and 23 for speaking</li></ul><p>For further information on eligibility to submit a maximum of two test sittings in a 12-month period, please refer to: AHPRA''s <a href="https://www.ahpra.gov.au/Registration/Registration-Standards/English-language-skills/Accepted-English-language-tests.aspx">accepted English language tests</a>.</p><p>ENGLISH REQUIREMENT for tests taken on or after 23 April 2026:</p><p><strong>Cambridge - </strong>C1 Advanced (Paper and computer at test centre only)</p><p>Minimum score of 178 with the following minimum band scores:</p><ul><li>Listening 175, Reading 179, Writing 180 and Speaking 194</li></ul><p><strong>Cambridge - </strong>C2 Proficiency (Paper and computer at test centre only)</p><p>Minimum score of 185 overall with the following band scores:</p><ul><li>minimum score of 185 in listening, reading and speaking, and</li><li>minimum score of 176 in writing.</li></ul><p><strong>IELTS - </strong>Academic paper and computer at test centre only</p><p><strong>Overall score of 7 with a minimum score of:</strong></p><ul><li>7 in listening, reading and speaking and,</li><li>6.5 in writing.</li></ul><p><strong>OET - </strong>On paper or computer based in testing centre. Any profession-specific OET test can be accepted.</p><p>Minimum overall score not applicable.</p><ul><li>Minimum band score of: Listening 350, Reading 360, Writing 350 and Speaking 360</li></ul><p><strong>PTE Academic - </strong>Computer at test centre only.</p><p>Minimum overall score of 63 with the following minimum band scores: Listening 58, Reading 59, Writing 60 and Speaking 76.</p><p><strong>TOEFL iBT - </strong>Computer at test centre only.</p><p>Minimum total score of 91 with a minimum score of: Listening 22, Reading 22, Writing 23 and Speaking 24.</p><p>For further information on eligibility to submit a maximum of two test sittings in a 12-month period, please refer to: AHPRA''s <a href="https://www.ahpra.gov.au/Registration/Registration-Standards/English-language-skills/Accepted-English-language-tests.aspx">accepted English language tests</a>.</p><p>The below listed documents are useful tools to assist you with your Nursing applications process, these documents are located on the:</p><ul><li><a href="https://international.cit.edu.au/courses/health_community/nursing/cit-vaccination-card.pdf">CIT Vaccination Card (PDF, 351.99 KB)</a></li><li><a href="https://international.cit.edu.au/courses/health_community/nursing/general-practitioners-letter.pdf">General practitioner''s letter (PDF, 285.21 KB)</a></li><li><a href="https://international.cit.edu.au/courses/health_community/nursing/inherent-nursing-requirements.pdf">Inherent Nursing requirements (PDF, 290.84 KB)</a></li><li><a href="https://international.cit.edu.au/courses/health_community/nursing/faq-for-diploma-of-nursing-HLT54121.pdf">FAQ for Diploma of Nursing (PDF, 731.1 KB)</a>.</li></ul><p>Students who achieve an overall IELTS 6.5 (Academic) may apply for the <a href="https://international.cit.edu.au/courses/health_community/ageing_support">Certificate III in Individual Support (Ageing)</a> or <a href="https://international.cit.edu.au/courses/health_community/disability">Certificate III in Individual Support (Disability)</a> which may provide a pathway into the Diploma of Nursing.</p><p>Students who achieve an overall IELTS 6.0 (Academic) may apply for the <a href="https://international.cit.edu.au/courses/health_community/mental_health">Certificate IV in Mental Health</a> which may provide a pathway into the Diploma of Nursing.</p><p>Upon completion of the Certificate III in Individual Support program or Certificate IV in Mental Health program, students must sit an IELTS test and meet the Diploma of Nursing English proficiency requirement as listed above.</p><p>All students will be <a href="http://www.ahpra.gov.au/Registration/Student-Registrations.aspx">registered with AHPRA</a> for the duration of the course.</p><p>This course has three mandatory clinical industry placements (400 hours in total). Provided in areas such as: Acute Care, Aged Care, Mental Health Rehabilitation, Community Nursing and Palliative Care. Before any clinical placements can commence, you will have to provide: a doctor''s certificate (to say you are fit to undertake nursing duties); evidence of commencement of required vaccinations; a First Aid Certificate valid for the duration of the course and a completed police check. CIT teachers will arrange all placements.</p>',
    apply_form = 'https://international.cit.edu.au/courses/health_community/nursing',
    updated_at = NOW()
WHERE cricos_course_code = '112865H';

UPDATE courses SET
    course_description = 'Real-World Culinary Experience at CIT<p>At Canberra Institute of Technology (CIT), Commercial Cookery students don’t just learn in the classroom — they compete, collaborate, and cook alongside the best in the industry.</p><p><strong>National Apprentice Competition:</strong> CIT students have the chance to enter this competition which includes a special category for culinary students. In 2024, one of our talented international students won the ACT round and advanced to compete in Melbourne.</p><p><strong>Celebrity &amp; Industry Chef Events: </strong>Our students regularly participate in exclusive Celebrity and Industry Chef Dinner Events, where they work side-by-side with renowned chefs from Canberra and beyond. These include culinary stars and chefs from award-winning Canberra restaurants, who visit CIT to mentor, present, and inspire the next generation of hospitality professionals.</p><p>Whether you''re dreaming of winning competitions or cooking with top chefs, CIT gives you the platform to make it happen.</p>Industry Placement<p>Establish future career opportunities and experience the industry first-hand with 600 hours of paid industry experience! (Approximate hours: Certificate III – 48 service periods (compulsory), with optional industry placement up to 400 hours. CIT offers support to connect students to restaurants and hotels for completing the 400 hours. Certificate IV – 200 hours.)</p>Why study at CIT?<ul><li>Four training kitchens on campus</li><li>In-house commercial restaurant and cafe</li><li>Learn from award-winning chefs</li><li>Use CIT''s network to connect you to employment opportunities</li><li>Be part of the exciting food scene in the Canberra region with plenty of job opportunities for hospitality students</li><li>Get support to find industry placement</li></ul>',
    total_course_duration = '<p><strong>CIT PACKAGE: 2 years</strong><br/>Certificate III: 1 year - Two semesters with 20-25 hours per week which includes service periods in CIT’s commercial restaurant kitchen</p><p>Certificate IV: 6 months</p><p>Diploma: 6 months</p><p><em>Take your career further by learning strategic, financial and personnel functions of the broader hospitality industry</em></p><p><strong>TOTAL CIT PACKAGE: 2 years</strong></p>',
    offshore_tuition_fee = 20720,
    onshore_tuition_fee = 20720,
    enrolment_fee = NULL,
    materials_fee = 750,
    entry_requirements = '<h4>Entry Requirements</h4> <p><strong>Academic requirements:</strong></p><ul><li>Year 12 Certificate or equivalent</li></ul><p><br/>Students over the age of 20 may be eligible for adult entry. Please refer to <a href="https://international.cit.edu.au/apply/entry_requirements">Entry Requirements</a> for more information.</p><p><strong>Literacy Skills Information</strong></p><p>We suggest that you will need Australian Core Skills Framework literacy levels of at least 3 across reading, writing, learning, oral communication and, depending on your course of study, numeracy skills to successfully complete this course. If you do not have this level, you can still enrol and seek support to improve your skills or you may prefer to begin with the lower level course.</p><p><strong>English requirements:</strong></p><ul><li>IELTS 6.0 (no band score less than 5.5)</li><li>PTE Academic - 50 (minimum of 42 in each band)</li><li>Cambridge English test (C1 Advanced and B2 First) - 169</li></ul><p>Applicants who will not be studying on a student visa, and who hold a temporary visa for the full duration of the offered course, will be required to meet Australian Core Skills Framework literacy levels of at least 3 in Language, Literacy, Numeracy and Digital skills (LLND) or equivalent.</p>',
    apply_form = 'https://international.cit.edu.au/courses/hospitality_culinary_tourism_events/commercial_cookery',
    updated_at = NOW()
WHERE cricos_course_code = '109761J';

