UPDATE courses SET
    course_description = '<p>Take your career to the next level with a management role in the diverse and ever-growing hospitality industry. This dynamic industry gives you the ability to work in hotels, restaurants, cafés, conference centres, private catering companies, healthcare environments or tourism and travel venues. These courses will provide you with substantial skills and knowledge to work internationally in almost any part of the industry and will give you specialised managerial skills in the areas of sales and marketing, human resources, financial management and business operations.</p><p><strong>Industry Placement</strong></p><p>You will undertake 36 service periods (216 hours) in the hospitality industry as part of this course. With the support of your CIT teachers, you will also gain casual employment opportunities in the hospitality industry to complement your studies!</p><p><strong>Additional Information</strong></p><p>Please see the <a href="https://international.cit.edu.au/courses/hospitality_culinary_tourism_events/hospitality/hospitality-uniform-and-equipment-requirements.pdf">uniform and equipment requirements (PDF, 129.17 KB)</a> for your practical classes.</p>',
    total_course_duration = '<p><strong>TOTAL CIT PACKAGE: 1 year</strong><br/>Certificate III: 6 months - 1 semester with a minimum of 20 hrs per week<br/>Diploma: 6 months - 1 semester with a minimum of 20 hrs per week</p>',
    offshore_tuition_fee = 8040,
    onshore_tuition_fee = 8040,
    enrolment_fee = NULL,
    materials_fee = 200,
    entry_requirements = '<h4>Entry Requirements</h4> <p><strong>Academic requirements:</strong></p><ul><li>Year 12 Certificate or equivalent</li></ul><p>Students over the age of 20 may be eligible for adult entry. Please refer to <a href="https://international.cit.edu.au/apply/entry_requirements">Entry Requirements</a> for more information.</p><p><strong>Literacy Skills Information</strong></p><p>We suggest that you will need Australian Core Skills Framework levels of at least 2 across reading, writing, learning, oral communication and, depending on your course of study, numeracy skills to successfully complete this course. If you do not have this level, you can still enrol and seek support to improve your skills, or you may prefer to begin with a lower-level course.</p><p><strong>English requirements:</strong></p><ul><li>IELTS 6.0 (no band score less than 5.5)</li><li>PTE Academic - 50 (minimum of 42 in each band)</li><li>Cambridge English test (C1 Advanced and B2 First) - 169</li></ul><p>Applicants who are not studying on a student visa and hold a temporary visa for the full duration of the offered course, will be required to meet Australian Core Skills Framework levels of at least 2 across reading, writing, learning, oral communication and, depending on your course of study, numeracy skills to successfully complete this course.</p>',
    apply_form = 'https://international.cit.edu.au/courses/hospitality_culinary_tourism_events/hospitality',
    updated_at = NOW()
WHERE cricos_course_code = '112089K';

