UPDATE courses SET
    course_description = '<p>Learn the art of making beautiful and complex dessert creations, where the only limit is your imagination. Our award-winning teaching staff will give you the specialist skills and knowledge you need to make your culinary dreams come true.</p><p>Train in world-class commercial kitchens and gain practical skills and experience to become a nationally recognised and qualified pastry chef. Master your skills in pastry making, chocolate and sugar work, yeast goods, gateaux, cake making, and petit fours.</p><p>Further your career options by learning high-level business, strategic, financial and personnel functions of the broader hospitality industry, with CIT’s Diploma course.</p>Additional Information<p>Please see the <a href="https://international.cit.edu.au/courses/hospitality_culinary_tourism_events/patisserie/patisserie-uniform-and-equipment-requirements.pdf">uniform and equipment requirements (PDF, 165.16 KB)</a> for your practical classes.</p>Industry Placement<p>Establish future career opportunities and experience the industry first-hand with 360 hours of paid industry experience.</p><p>To successfully complete this course, you must undertake mandatory work placement of 12 service periods, this can be completed in the CIT Restaurant or through Industry placement.</p>Why study at CIT?<ul><li>Four training kitchens on campus</li><li>In-house commercial restaurant and cafe</li><li>Learn from award-winning chefs</li><li>Use CIT''s network to connect you to employment opportunities</li><li>Be part of the exciting food scene in the Canberra region with plenty of job opportunities for hospitality students</li><li>Get support to find industry placement</li></ul>',
    total_course_duration = '<p><strong>CIT PACKAGE: 1.5</strong><br/><strong>Certificate III:</strong> 1 year - 12 months full-time attending 3 days per week including a compulsory commercial kitchen placement<br/><strong>Certificate IV:</strong> 1 unit of competency (concurrent with diploma)<br/><strong>Diploma: </strong>6 months - 1 semester with a minimum of 20 hrs per week</p><p><strong>TOTAL CIT PACKAGE: 1.5</strong></p>',
    offshore_tuition_fee = 20290,
    onshore_tuition_fee = 20290,
    enrolment_fee = NULL,
    materials_fee = 630,
    entry_requirements = '<h4>Entry Requirements</h4> <p><strong>Academic requirements:</strong></p><ul><li>Year 12 Certificate or equivalent</li></ul><p><br/>Students over the age of 20 may be eligible for adult entry. Please refer to <a href="https://international.cit.edu.au/apply/entry_requirements">Entry Requirements</a> for more information.</p><p><strong>Literacy Skills Information</strong></p><p>We suggest that you will need Australian Core Skills Framework literacy levels of at least 3 across reading, writing, learning, oral communication and, depending on your course of study, numeracy skills to successfully complete this course. If you do not have this level, you can still enrol and seek support to improve your skills, or you may prefer to begin with the lower level course.</p><p><strong>English requirements:</strong></p><ul><li>IELTS 6.0 (no band score less than 5.5)</li><li>PTE Academic - 50 (minimum of 42 in each band)</li><li>Cambridge English test (C1 Advanced and B2 First) - 169</li></ul><p>Applicants who will not be studying on a student visa and who hold a temporary visa for the full duration of the offered course will be required to meet Australian Core Skills Framework literacy levels of at least 3 in Language, Literacy, Numeracy and Digital skills (LLND) or equivalent.</p>',
    apply_form = 'https://international.cit.edu.au/courses/hospitality_culinary_tourism_events/patisserie',
