UPDATE courses SET
    course_description = '<p>This qualification reflects the role of highly skilled senior operators who use a broad range of tourism or travel skills combined with managerial skills and sound knowledge of industry operations to coordinate travel or tourism operations. They operate independently, have responsibility for others, and make a range of operational business decisions. <br/><br/>This qualification provides a pathway to work in many travel and tourism industry sectors as a departmental or small business manager. The diversity of employers includes travel agencies, tour wholesalers, tour operators, inbound tour operators, hotels, holiday parks and resorts, tourist attractions, visitor information centres, and other tourism businesses. <br/><br/>This qualification will include an unpaid industry work placement to further your skills and knowledge in the industry and support your learning and assessment.</p>',
    total_course_duration = '<p><strong>TOTAL CIT PACKAGE: 1 year</strong><br/>Diploma: 1 year - 2 semesters with approx. 25 hours of study per week</p>',
    offshore_tuition_fee = 16070,
    onshore_tuition_fee = 16070,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4> <p><strong>Academic requirements:</strong></p><ul><li>ACT Year 12 Certificate or equivalent</li></ul><p><br/>Students over the age of 20 may be eligible for adult entry. Please refer to <a href="https://international.cit.edu.au/apply/entry_requirements">Entry Requirements</a> for more information.</p><p><strong>Literacy Skills Information</strong></p><p>We suggest that you will need Australian Core Skills Framework literacy levels of at least 4 across reading, writing, learning, oral communication and, depending on your course of study, numeracy skills to successfully complete this course. If you do not have this level, you can still enrol and seek support to improve your skills, or you may prefer to begin with the lower-level course.</p><p><strong>English requirements:</strong></p><ul><li>IELTS 6.0 (no band score less than 5.0)</li><li>PTE Academic - 50 (minimum of 36 in each band)</li><li>Cambridge English test (C1 Advanced and B2 First) - 169</li></ul><p>Applicants who are not studying on a student visa and hold a temporary visa for the full duration of the offered course will be required to meet Australian Core Skills Framework literacy levels of at least 4 across reading, writing, learning, oral communication and, depending on your course of study, numeracy skills to successfully complete this course.</p>',
    apply_form = 'https://international.cit.edu.au/courses/hospitality_culinary_tourism_events/tourism',
    updated_at = NOW()
WHERE cricos_course_code = '113905H';

UPDATE courses SET
    course_description = 'Certificate III<p>This course provides the required skills and knowledge to be competent in a wide range of Information and Communications Technology (ICT) roles. It provides a pathway into Networking, Programming and Cyber Security entry employment opportunities or further studies.</p><p>On completion, you will have the skills and knowledge to apply and support IT activities in the workplace across a wide range of ICT areas, including technical support, network administration, website creation, digital media technologies, coding skills and programming frameworks, virtual computing and basic cyber security and computer hardware skills.</p><p>The Certificate III will be delivered ast CIT Tuggeranong.</p>Certificate IV<p>This qualification provides you with the skills and knowledge to be competent in a wide range of general Information and Communication Technologies (ICT) and to support small to medium enterprises (SMEs). The course will equip you with the skills and knowledge to problem solve, basic networking and infrastructure design, database and web development using various programs and implement cyber security risk management strategies.</p><p>The Certificate IV will be delivered at CIT Woden.</p>Diploma<p>This qualification provides you with the skills and knowledge to administer and manage information and communications technology (ICT) support in small-to-medium enterprises (SMEs) using a wide range of general ICT technologies and cyber security practices.</p><p>The Diploma will be delivered at CIT Woden.</p>',
    total_course_duration = '<p><strong>TOTAL CIT PACKAGE: 2.5 years</strong><br/></p><p>Certificate III: 6 months - 1 semester with a minimum of 20 hours of study per week over 16 weeks</p><p>Certificate IV: 1 year - 2 semesters with a minimum of 20 hours per week</p><p>Diploma: 1 year - 2 semesters with a minimum of 20 hours of study per week over 16 weeks, including face-to-face and virtual delivery.</p><p>For each of these courses it is expected students will spend approximately the same number of hours in private study to practice skills and apply knowledge learnt.</p><p>CT has weekly practical lab activities students are advised to complete weekly to enable successful completion of assessments.</p>',
    offshore_tuition_fee = 8040,
    onshore_tuition_fee = 8040,
    enrolment_fee = NULL,
    materials_fee = 60,
    entry_requirements = '<h4>Entry Requirements</h4> <p><strong>Academic requirements:</strong></p><ul><li>Year 12 Certificate (or equivalent) or Adult Entry</li><li>Knowledge of MS applications and windows environments is recommended for commencement in Certificate III of this pathway.</li></ul><p>Students over the age of 20 may be eligible for adult entry. Please refer to <a href="https://international.cit.edu.au/apply/entry_requirements">Entry Requirements</a> for more information.</p><p><strong>Literacy Skills Information</strong></p><p>We suggest that you will need Australian Core Skills Framework literacy levels of at least 3 across reading, writing, learning, oral communication and, depending on your course of study, numeracy skills to successfully complete this course. If you do not have this level, you can still enrol and seek support to improve your skills, or you may prefer to begin with the lower-level course. Please visit <a href="https://cit.edu.au/courses/education-community/foundation-skills">Foundation Skills</a>.</p><p><strong>English requirements:</strong></p><p>Students must meet <strong>one</strong> of the following English requirements:</p><ul><li>IELTS 6.0 (no band score less than 5.0)</li><li>PTE Academic - 50 (minimum of 36 in each band)</li><li>Cambridge English test (C1 Advanced and B2 First) - 169</li></ul><p>Applicants who are not studying on a student visa and hold a temporary visa for the full duration of the offered course will be required to meet Australian Core Skills Framework levels of at least 3 across reading, writing, learning, oral communication and, depending on your course of study, numeracy skills to successfully complete this course.</p>',
    apply_form = 'https://international.cit.edu.au/courses/information_technology/it',
    updated_at = NOW()
WHERE cricos_course_code = '108479H';

